// Qué se ha enviado: archivo PDF, archivo de texto (.txt/.md) o texto pegado.
const j = $json;
const bin = $input.first().binary || {};
const campo = Object.keys(bin)[0] || '';
const archivo = campo ? bin[campo] : null;
const nombre = archivo?.fileName || '';
const ext = nombre.toLowerCase().split('.').pop();
if (archivo && !['pdf', 'txt', 'md', 'markdown'].includes(ext)) throw new Error('Formato no admitido. Usa .txt, .md o .pdf.');
const pegado = String(j['Texto'] || '').trim();
if (!archivo && !pegado) throw new Error('Sube un archivo o pega un texto.');
const titulo = String(j['Título'] || '').trim() || nombre.replace(/\.[^.]+$/, '') || 'Sin título';
return [{ json: { titulo: titulo.slice(0, 200), campo, tipo: archivo ? (ext === 'pdf' ? 'pdf' : 'texto') : 'pegado',
                  fuente: archivo ? `archivo:${nombre}` : 'texto', texto: pegado }, binary: bin }];

// Troceado igual que rag.ts: ~800 caracteres con 100 de solapamiento, respetando párrafos y frases.
// Sale un item por lote de 20 fragmentos (una llamada a la función embed por lote).
const TAM = 800, SOLAPE = 100, LOTE = 20;
const d = $('Detectar').first().json;
const texto = String($json.text ?? $json.data ?? d.texto ?? '').slice(0, 300000);

function partirLargo(t) {
  const out = [];
  for (const f of t.split(/(?<=[.!?…;:])\s+/)) {
    if (f.length <= TAM) { out.push(f); continue; }
    let actual = '';
    for (const p of f.split(/\s+/)) {
      if ((actual + ' ' + p).length > TAM && actual) { out.push(actual); actual = p; }
      else actual = actual ? actual + ' ' + p : p;
    }
    if (actual) out.push(actual);
  }
  return out;
}
function cola(t, n) {
  if (t.length <= n) return t;
  const s = t.slice(-n), e = s.indexOf(' ');
  return e > 0 ? s.slice(e + 1) : s;
}
function trocear(t) {
  const limpio = t.replace(/\r\n?/g, '\n').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  if (!limpio) return [];
  const piezas = [];
  let enc = '';
  for (const p of limpio.split(/\n\s*\n/)) {
    let par = p.trim();
    if (!par) continue;
    // Un título suelto se pega al párrafo siguiente.
    if ((/^#{1,6}\s/.test(par) && !par.includes('\n')) || (par.length < 80 && par.endsWith(':'))) { enc += (enc ? '\n' : '') + par; continue; }
    if (enc) { par = `${enc}\n${par}`; enc = ''; }
    if (par.length <= TAM) piezas.push(par); else piezas.push(...partirLargo(par));
  }
  if (enc) piezas.push(enc);
  const trozos = [];
  let actual = '';
  for (const pieza of piezas) {
    const sep = actual ? '\n\n' : '';
    if ((actual + sep + pieza).length <= TAM) actual += sep + pieza;
    else {
      if (actual) trozos.push(actual);
      const s = actual ? cola(actual, SOLAPE) : '';
      actual = s && (s.length + 1 + pieza.length) <= TAM + SOLAPE ? s + ' ' + pieza : pieza;
    }
  }
  if (actual) trozos.push(actual);
  return trozos;
}

const trozos = trocear(texto);
if (!trozos.length) throw new Error('El documento no contiene texto aprovechable (¿PDF escaneado?).');
if (trozos.length > 400) throw new Error(`Documento demasiado grande (${trozos.length} fragmentos; máximo 400). Divídelo en partes.`);
const lotes = [];
for (let i = 0; i < trozos.length; i += LOTE) {
  const t = trozos.slice(i, i + LOTE);
  // El título va dentro del texto embebido para dar contexto al fragmento (como rag.ts).
  lotes.push({ json: { desde: i, trozos: t, textos: t.map(x => `${d.titulo}\n${x}`), total: trozos.length } });
}
return lotes;

// Empareja cada lote con sus embeddings y deja las filas listas (falta el id del documento).
const lotes = $('Trocear').all();
const embs = $input.all();
const filas = [];
lotes.forEach((l, i) => l.json.trozos.forEach((t, k) => {
  const e = embs[i]?.json.embeddings?.[k];
  if (!e || e.length !== 384) throw new Error(`Falta el embedding del fragmento ${l.json.desde + k}.`);
  filas.push({ contenido: t, embedding: JSON.stringify(e), orden: l.json.desde + k });
}));
const d = $('Detectar').first().json;
return [{ json: { titulo: d.titulo, fuente: d.fuente, filas } }];

// Añade el id del documento recién creado a cada fragmento.
const u = $('Unir embeddings').first().json;
return [{ json: { documento_id: $json.id, titulo: u.titulo, total: u.filas.length, filas: u.filas.map(f => ({ documento_id: $json.id, ...f })) } }];
